     1	/**
     2	 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
     5	 */
     6	import { subscribe } from "@/lib/event-bus";
     7	import { isEnabled } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { consumeRateLimit } from "@/lib/rate-limit";
    10	import { assertOrgScope } from "@/lib/tenant";
    11	import * as commentRepo from "@/server/repositories/comment-repository";
    12	import * as issueRepo from "@/server/repositories/issue-repository";
    13	import * as orgRepo from "@/server/repositories/organization-repository";
    14	import * as projectRepo from "@/server/repositories/project-repository";
    15	import * as searchRepo from "@/server/repositories/search-repository";
    16	import { orgResource } from "./_support";
    17	import type { SearchQueryInput } from "@/schemas/search";
    18	import type { SearchSubjectKind } from "@/server/repositories/search-repository";
    19	import type { Comment } from "@/types/comment";
    20	import type { OrgId, Page } from "@/types/common";
    21	import type { Unsubscribe } from "@/types/event";
    22	import type { Issue } from "@/types/issue";
    23	import type { Actor } from "@/types/member";
    24	import type { Project } from "@/types/project";
    25	
    26	export type SearchHit = {
    27	  kind: SearchSubjectKind;
    28	  id: string;
    29	  title: string;
    30	  snippet: string;
    31	  href: string;
    32	};
    33	
    34	/** Characters of surrounding context kept on either side of a match. */
    35	const SNIPPET_RADIUS = 60;
    36	
    37	/** Token bucket protecting the index from query bursts. */
    38	const SEARCH_QUERY_BUCKET = "search:query";
    39	
    40	/**
    41	 * Runs a query against the denormalised index. Field-scoped syntax
    42	 * (`status:done`) is an `advanced_search` feature, so a query containing a
    43	 * colon is rejected for plans that do not include it rather than silently
    44	 * being treated as literal text.
    45	 */
    46	export async function search(
    47	  actor: Actor,
    48	  input: SearchQueryInput,
    49	): Promise<Page<SearchHit>> {
    50	  assertOrgScope(actor, input.orgId);
    51	  assertCan(actor, "issue:read", orgResource(input.orgId));
    52	
    53	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
    54	  if (!verdict.allowed) {
    55	    throw new Error(
    56	      `Search rate limit reached; try again after ${verdict.resetAt}`,
    57	    );
    58	  }
    59	
    60	  const org = await orgRepo.findOrgById(input.orgId);
    61	  const advanced = isEnabled("advanced_search", {
    62	    orgId: input.orgId,
    63	    userId: actor.userId,
    64	    plan: org?.plan ?? "free",
    65	    role: actor.role,
    66	    overrides: org?.settings.enabledFlagOverrides,
    67	  });
    68	
    69	  if (input.q.includes(":") && !advanced) {
    70	    throw new Error("Field-scoped search is not included in this plan");
    71	  }
    72	
    73	  const text = normaliseQuery(input.q);
    74	  const page = await searchRepo.searchDocuments({ ...input, q: text });
    75	
    76	  return {
    77	    items: page.items.map((row) => ({
    78	      kind: row.subjectKind,
    79	      id: row.subjectId,
    80	      title: row.content.split("\n")[0] ?? row.subjectId,
    81	      snippet: snippetAround(row.content, text),
    82	      href: hrefFor(row.subjectKind, row.subjectId),
    83	    })),
    84	    nextCursor: page.nextCursor,
    85	    total: page.total,
    86	  };
    87	}
    88	
    89	/**
    90	 * Strips the field tokens the dialog has already applied (`kind:`, `in:`,
    91	 * `project:`), so the index only ever sees the free text. The dialog's parser
    92	 * in `components/domain/search/query-syntax.ts` is the reference for what a
    93	 * token looks like.
    94	 */
    95	function normaliseQuery(raw: string): string {
    96	  return raw.trim().replace(/\s+/g, " ");
    97	}
    98	
    99	export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
   100	  await searchRepo.upsertSearchDocument(
   101	    orgId,
   102	    "issue",
   103	    issue.id,
   104	    [issue.title, issue.description ?? ""].join("\n"),
   105	    issue.projectId,
   106	  );
   107	}
   108	
   109	export async function indexComment(
   110	  orgId: OrgId,
   111	  comment: Comment,
   112	): Promise<void> {
   113	  await searchRepo.upsertSearchDocument(
   114	    orgId,
   115	    "comment",
   116	    comment.id,
   117	    comment.body,
   118	    null,
   119	  );
   120	}
   121	
   122	export async function indexProject(
   123	  orgId: OrgId,
   124	  project: Project,
   125	): Promise<void> {
   126	  await searchRepo.upsertSearchDocument(
   127	    orgId,
   128	    "project",
   129	    project.id,
   130	    [project.name, project.description ?? ""].join("\n"),
   131	    project.id,
   132	  );
   133	}
   134	
   135	export async function removeFromIndex(
   136	  orgId: OrgId,
   137	  subjectKind: SearchSubjectKind,
   138	  subjectId: string,
   139	): Promise<void> {
   140	  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
   141	}
   142	
   143	/**
   144	 * Keeps the index in step with writes. Every handler re-reads the row rather
   145	 * than trusting the event payload, so a partially-applied write can never be
   146	 * indexed as if it had succeeded.
   147	 */
   148	export function registerSearchListeners(): Unsubscribe {
   149	  const offs: Unsubscribe[] = [
   150	    subscribe("issue.created", async (payload) => {
   151	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
   152	      if (issue) await indexIssue(payload.orgId, issue);
   153	    }),
   154	    subscribe("issue.updated", async (payload) => {
   155	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
   156	      if (issue) await indexIssue(payload.orgId, issue);
   157	    }),
   158	    subscribe("issue.archived", async (payload) => {
   159	      await removeFromIndex(payload.orgId, "issue", payload.issueId);
   160	    }),
   161	    subscribe("comment.created", async (payload) => {
   162	      const comment = await commentRepo.findCommentById(
   163	        payload.orgId,
   164	        payload.commentId,
   165	      );
   166	      if (comment) await indexComment(payload.orgId, comment);
   167	    }),
   168	    subscribe("comment.deleted", async (payload) => {
   169	      await removeFromIndex(payload.orgId, "comment", payload.commentId);
   170	    }),
   171	    subscribe("project.created", async (payload) => {
   172	      const project = await projectRepo.findProjectById(
   173	        payload.orgId,
   174	        payload.projectId,
   175	      );
   176	      if (project) await indexProject(payload.orgId, project);
   177	    }),
   178	    subscribe("project.archived", async (payload) => {
   179	      await removeFromIndex(payload.orgId, "project", payload.projectId);
   180	    }),
   181	    subscribe("search.reindex_requested", async (payload) => {
   182	      if (payload.subjectKind !== "issue") return;
   183	      const issue = await issueRepo.findIssueById(
   184	        payload.orgId,
   185	        payload.subjectId as Issue["id"],
   186	      );
   187	      if (issue) await indexIssue(payload.orgId, issue);
   188	    }),
   189	  ];
   190	
   191	  return () => {
   192	    for (const off of offs) off();
   193	  };
   194	}
   195	
   196	function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
   197	  switch (kind) {
   198	    case "issue":
   199	      return `/issues/${subjectId}`;
   200	    case "comment":
   201	      return `/comments/${subjectId}`;
   202	    case "project":
   203	      return `/projects/${subjectId}`;
   204	  }
   205	}
   206	
   207	function snippetAround(content: string, query: string): string {
   208	  const at = content.toLowerCase().indexOf(query.toLowerCase());
   209	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
   210	
   211	  const start = Math.max(0, at - SNIPPET_RADIUS);
   212	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
   213	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
   214	    end < content.length ? "…" : ""
   215	  }`;
   216	}
