    15	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    16	import { withAction } from "@/actions/_lib/with-action";
    17	import { can } from "@/lib/permissions";
    18	import { searchQuerySchema, type SearchQueryInput } from "@/schemas/search";
    19	import { search, type SearchHit } from "@/server/services/search-service";
    20	import type { ActionResult } from "@/types/api";
    21	
    22	const run = withAction<typeof searchQuerySchema, SearchHit[]>(
    23	  searchQuerySchema,
    24	  async (raw, actor) => {
    25	    const input = raw as SearchQueryInput;
    26	
    27	    if (!can(actor, "org:read", { kind: "organization", orgId: input.orgId })) {
    28	      throw new ForbiddenActionError("org:read");
    29	    }
