     1	"use client";
     2	
     3	/**
     4	 * Ctrl+K search overlay; advanced syntax requires `advanced_search`.
     5	 *
     6	 * Must call (do not reimplement): isEnabled
     7	 */
     8	import { useEffect, useState } from "react";
     9	import { Dialog } from "@/components/ui/dialog";
    10	import { Input } from "@/components/ui/input";
    11	import { Spinner } from "@/components/ui/spinner";
    12	import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
    13	import { useDebouncedValue } from "@/hooks/use-debounced-value";
    14	import { isEnabled } from "@/lib/feature-flags";
    15	import type { SearchQueryInput } from "@/schemas/search";
    16	import type { SearchHit } from "@/server/services/search-service";
    17	import type { ActionResult } from "@/types/api";
    18	import type { OrgId } from "@/types/common";
    19	import type { FeatureFlagSnapshot } from "@/types/feature-flag";
    20	import type { ReactElement } from "react";
    21	import { describeQuery, parseSearchQuery } from "./query-syntax";
    22	import { SearchResults } from "./search-results";
    23	
    24	export type SearchDialogProps = {
    25	  open: boolean;
    26	  orgId: OrgId;
    27	  flags: FeatureFlagSnapshot;
    28	  onClose: () => void;
    29	  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
    30	};
    31	
    32	const SEARCH_PAGE_SIZE = 20;
    33	
    34	export function SearchDialog(props: SearchDialogProps): ReactElement | null {
    35	  const { open, orgId, flags, onClose, onSearch } = props;
    36	
    37	  const [raw, setRaw] = useState("");
    38	  // Results are stored together with the query that produced them, so
    39	  // "still searching" is derived rather than a second piece of state that
    40	  // could disagree with the first.
    41	  const [results, setResults] = useState<{
    42	    query: string;
    43	    hits: readonly SearchHit[];
    44	  }>({ query: "", hits: [] });
    45	
    46	  const debounced = useDebouncedValue(raw);
    47	  const advanced =
    48	    flags.advanced_search === true ||
    49	    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
    50	  const parsed = parseSearchQuery(debounced, advanced);
    51	
    52	  const query = parsed.text;
    53	  const pending = query.length > 0 && results.query !== query;
    54	
    55	  useEffect(() => {
    56	    if (!open || query.length === 0) return;
    57	
    58	    let cancelled = false;
    59	
    60	    void onSearch({
    61	      orgId,
    62	      q: query,
    63	      kinds: [...parsed.kinds],
    64	      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
    65	      limit: SEARCH_PAGE_SIZE,
    66	    }).then((result) => {
    67	      if (cancelled) return;
    68	      setResults({ query, hits: result.ok ? result.data : [] });
    69	    });
    70	
    71	    return () => {
    72	      cancelled = true;
    73	    };
    74	    // `parsed` is derived from the debounced string; depending on its parts
    75	    // keeps the effect from re-firing on every keystroke.
    76	  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);
    77	
    78	  if (!open) return null;
    79	
    80	  return (
    81	    <Dialog
    82	      open={open}
    83	      title="Search"
    84	      description={
    85	        advanced
    86	          ? "Use kind:issue or project:<id> to narrow the search."
    87	          : undefined
    88	      }
    89	      onClose={onClose}
    90	    >
    91	      <Input
    92	        name="q"
    93	        type="search"
    94	        value={raw}
    95	        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
    96	        onChange={setRaw}
    97	      />
    98	
    99	      {advanced && debounced.length > 0 ? (
   100	        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
   101	      ) : null}
   102	
   103	      <div className="mt-3">
   104	        {pending ? (
   105	          <Spinner size="sm" label="Searching" />
   106	        ) : (
   107	          <SearchResults
   108	            hits={results.query === query ? results.hits : []}
   109	            query={query}
   110	            onSelect={() => onClose()}
   111	          />
   112	        )}
   113	      </div>
   114	    </Dialog>
   115	  );
   116	}
