     3	/**
     4	 * Builds the Ctrl+K command groups from the actor's permissions and flags.
     5	 *
     6	 * Must call (do not reimplement): can, isEnabled
     7	 */
     8	import { useCallback, useMemo, useState } from "react";
     9	import { isEnabled } from "@/lib/feature-flags";
    10	import type { CommandGroup } from "@/components/ui/command-palette";
    11	import { buildCommandGroups } from "./command-groups";
    12	import { orgFlagContext } from "./flag-context";
    13	import { useKeyboardShortcut } from "./use-keyboard-shortcut";
    14	import { useOrg } from "./use-org";
    15	
    16	export const COMMAND_PALETTE_SHORTCUT: readonly string[] = ["mod", "k"];
    17	
    18	export function useCommandPalette(): {
    19	  open: boolean;
    20	  setOpen: (open: boolean) => void;
    21	  groups: readonly CommandGroup[];
    22	} {
    23	  const { org, actor, flags } = useOrg();
    24	  const [open, setOpen] = useState(false);
    25	
    26	  // The palette itself is a flag; when it is off the shortcut must not bind.
    27	  const paletteEnabled =
    28	    flags.command_palette === true ||
    29	    isEnabled("command_palette", orgFlagContext(org, actor));
    30	
    31	  const toggle = useCallback(() => setOpen((current) => !current), []);
    32	  useKeyboardShortcut(COMMAND_PALETTE_SHORTCUT, toggle, paletteEnabled);
    33	
    34	  const groups = useMemo(
    35	    () => (paletteEnabled ? buildCommandGroups(org, actor, flags) : []),
    36	    [paletteEnabled, org, actor, flags],
    37	  );
    38	
    39	  return { open: open && paletteEnabled, setOpen, groups };
    40	}
