     1	/**
     2	 * Builds the Ctrl+K command list for one actor.
     3	 *
     4	 * Every entry names the permission and/or flag that gates it and is then
     5	 * filtered through `can()` and `isEnabled()` — the palette must never offer a
     6	 * command the actor would be refused, and it must never invent its own idea of
     7	 * who may do what. Kept pure so the filtering can be tested directly.
     8	 */
     9	import { isEnabled } from "@/lib/feature-flags";
    10	import { can } from "@/lib/permissions";
    11	import {
    12	  activityResource,
    13	  billingResource,
    14	  organizationResource,
    15	} from "@/components/domain/permission/resources";
    16	import type {
    17	  CommandGroup,
    18	  CommandItemSpec,
    19	} from "@/components/ui/command-palette";
    20	import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
    21	import type { Actor } from "@/types/member";
    22	import type { Organization } from "@/types/organization";
    23	import type { PermissionAction, PermissionResource } from "@/types/permission";
    24	import { orgFlagContext } from "./flag-context";
    25	
    26	/** A palette entry plus the gates it depends on. */
    27	export interface CommandSpec extends CommandItemSpec {
    28	  readonly heading: string;
    29	  readonly action?: PermissionAction;
    30	  readonly flag?: FeatureFlagKey;
    31	  /** Which resource the permission is asked about; defaults to the org. */
    32	  readonly scope?: "organization" | "billing" | "activity";
    33	}
    34	
    35	export const COMMAND_SPECS: readonly CommandSpec[] = [
    36	  { heading: "Create", id: "create:issue", label: "New issue", shortcut: "c", action: "issue:create" },
    37	  { heading: "Create", id: "create:project", label: "New project", action: "project:create" },
    38	  { heading: "Create", id: "create:invite", label: "Invite teammate", action: "member:invite" },
    39	  { heading: "Go to", id: "nav:issues", label: "Issues", shortcut: "g i", action: "issue:read" },
    40	  { heading: "Go to", id: "nav:projects", label: "Projects", shortcut: "g p", action: "project:read" },
    41	  { heading: "Go to", id: "nav:board", label: "Board", shortcut: "g b", action: "issue:read", flag: "kanban_board" },
    42	  { heading: "Go to", id: "nav:members", label: "Members", action: "member:read" },
    43	  {
    44	    heading: "Go to",
    45	    id: "nav:activity",
    46	    label: "Activity",
    47	    action: "activity:read",
    48	    flag: "activity_feed",
    49	    scope: "activity",
    50	  },
    51	  {
    52	    heading: "Go to",
    53	    id: "nav:billing",
    54	    label: "Billing",
    55	    action: "org:manage_billing",
    56	    scope: "billing",
    57	  },
    58	  {
    59	    heading: "Export",
    60	    id: "export:issues",
    61	    label: "Export issues as CSV",
    62	    hint: "Downloads the current filter",
    63	    action: "issue:read",
    64	    flag: "csv_export",
    65	  },
    66	  {
    67	    heading: "Export",
    68	    id: "export:activity",
    69	    label: "Export audit log as CSV",
    70	    action: "activity:export",
    71	    flag: "csv_export",
    72	    scope: "activity",
    73	  },
    74	];
    75	
    76	function resourceFor(spec: CommandSpec, actor: Actor): PermissionResource {
    77	  switch (spec.scope) {
    78	    case "billing":
    79	      return billingResource(actor.orgId);
    80	    case "activity":
    81	      return activityResource(actor.orgId);
    82	    default:
    83	      // Creation and navigation are not scoped to an existing row, so the
    84	      // organization is the resource the role matrix is asked about.
    85	      return organizationResource(actor.orgId);
    86	  }
    87	}
    88	
    89	export function buildCommandGroups(
    90	  org: Organization,
    91	  actor: Actor,
    92	  flags: FeatureFlagSnapshot,
    93	): readonly CommandGroup[] {
    94	  const context = orgFlagContext(org, actor);
    95	  // The snapshot was evaluated when the layout rendered; a flag flipped since
    96	  // then is still honoured by re-evaluating against the live context.
    97	  const flagOn = (flag: FeatureFlagKey): boolean =>
    98	    flags[flag] === true || isEnabled(flag, context);
    99	
   100	  const groups = new Map<string, CommandItemSpec[]>();
   101	
   102	  for (const spec of COMMAND_SPECS) {
   103	    if (spec.flag !== undefined && !flagOn(spec.flag)) continue;
   104	    if (
   105	      spec.action !== undefined &&
   106	      !can(actor, spec.action, resourceFor(spec, actor))
   107	    ) {
   108	      continue;
   109	    }
   110	    const items = groups.get(spec.heading) ?? [];
   111	    items.push({
   112	      id: spec.id,
   113	      label: spec.label,
   114	      ...(spec.hint !== undefined ? { hint: spec.hint } : {}),
   115	      ...(spec.shortcut !== undefined ? { shortcut: spec.shortcut } : {}),
   116	    });
   117	    groups.set(spec.heading, items);
   118	  }
   119	
   120	  return [...groups.entries()].map(([heading, items]) => ({ heading, items }));
   121	}

