     1	import { describe, expect, it } from "vitest";
     2	import {
     3	  describeQuery,
     4	  parseSearchQuery,
     5	} from "@/components/domain/search/query-syntax";
     6	
     7	describe("query-syntax/parseSearchQuery", () => {
     8	  it("treats everything as free text when the flag is off", () => {
     9	    const parsed = parseSearchQuery("kind:comment deploy", false);
    10	    expect(parsed.text).toBe("kind:comment deploy");
    11	    expect(parsed.kinds).toEqual(["issue"]);
    12	  });
    13	
    14	  it("extracts kind tokens when the flag is on", () => {
    15	    const parsed = parseSearchQuery("kind:comment deploy", true);
    16	    expect(parsed.text).toBe("deploy");
    17	    expect(parsed.kinds).toEqual(["comment"]);
    18	  });
    19	
    20	  it("accepts the plural and the in: alias", () => {
    21	    expect(parseSearchQuery("in:projects roadmap", true).kinds).toEqual([
    22	      "project",
    23	    ]);
    24	  });
    25	
    26	  it("collects several kinds", () => {
    27	    expect(
    28	      parseSearchQuery("kind:issue kind:comment flaky", true).kinds,
    29	    ).toEqual(["issue", "comment"]);
    30	  });
    31	
    32	  it("extracts a project filter", () => {
    33	    const parsed = parseSearchQuery("project:prj_7 latency", true);
    34	    expect(parsed.projectId).toBe("prj_7");
    35	    expect(parsed.text).toBe("latency");
    36	  });
    37	
    38	  it("reports tokens it did not understand instead of searching for them", () => {
    39	    const parsed = parseSearchQuery("author:ada bug", true);
    40	    expect(parsed.unknownTokens).toEqual(["author:ada"]);
    41	    expect(parsed.text).toBe("bug");
    42	  });
    43	
    44	  it("keeps a leading colon as ordinary text", () => {
    45	    expect(parseSearchQuery(":wat", true).text).toBe(":wat");
    46	  });
    47	
    48	  it("falls back to the default kind when only syntax was typed", () => {
    49	    expect(parseSearchQuery("project:prj_7", true).kinds).toEqual(["issue"]);
    50	  });
    51	});
    52	
    53	describe("query-syntax/describeQuery", () => {
    54	  it("summarises what the parser understood", () => {
    55	    const parsed = parseSearchQuery("kind:comment project:prj_1 nope:x hi", true);
    56	    const description = describeQuery(parsed);
