/**
 * The `advanced_search` query language (ADR 0007). This module is the one
 * parser: the dialog's hint line and the server's query execution both call
 * `parseSearchQuery`, so what the dialog says it understood is what gets
 * searched.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];

/** A field token starts with a letter, so `2:` or `:wat` stay ordinary text. */
const FIELD_TOKEN = /^([A-Za-z][A-Za-z_-]*):(.*)$/;

export interface ParsedSearchQuery {
  /** The free-text remainder, with every recognised token removed. */
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];
export const ALL_SEARCH_KINDS: readonly SearchSubjectKind[] = KINDS;

/**
 * @param raw            what the user typed
 * @param advanced       whether the `advanced_search` flag is on for this org;
 *                       when false the whole string is free text, so a colon in
 *                       a title still finds the title, and only issues are searched
 * @param requestedKinds the kinds the caller asked for; `kind:` tokens override
 *                       them when present (advanced only)
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
  requestedKinds: readonly SearchSubjectKind[] = DEFAULT_SEARCH_KINDS,
): ParsedSearchQuery {
  if (!advanced) {
    return {
      text: raw.trim().replace(/\s+/g, " "),
      kinds: DEFAULT_SEARCH_KINDS,
      projectId: null,
      unknownTokens: [],
    };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
    const match = FIELD_TOKEN.exec(token);
    if (match === null) {
      terms.push(token);
      continue;
    }

    const field = match[1]!.toLowerCase();
    const value = match[2]!;
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (KINDS.includes(kind)) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds: kinds.length > 0 ? [...new Set(kinds)] : [...requestedKinds],
    projectId,
    unknownTokens: unknown,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}

/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects, issues and comments, page by page, and
 * re-upserts every document. Scoped to a single org on purpose: a full-fleet
 * reindex is a sequence of these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
      });

      for (const project of projects.items) {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
      });

      for (const issue of issues.items) {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
          await reindexComments(orgId, issue.id, result);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);
  });
}

async function reindexComments(
  orgId: OrgId,
  issueId: IssueId,
  result: JobResult,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const comments = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: PAGE_SIZE,
      cursor,
    });

    for (const comment of comments.items) {
      await indexComment(orgId, comment);
      result.processed += 1;
    }

    cursor = comments.nextCursor;
  } while (cursor !== null);
}

/**
 * Full-page search results.
 *
 * Owner D. The command palette and this page share one action, so the flag
 * check has to live in both places — the palette narrows what it asks for, and
 * this page explains why comments are missing from the results.
 *
 * Must call (do not reimplement): isEnabled
 */

import Link from "next/link";
import type { Metadata } from "next";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { search as runSearch } from "@/server/services/search-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Search",
};

const RESULT_LIMIT = 30;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const advanced = isEnabled("advanced_search", buildFlagContext(actor, org));
  const query = typeof search.q === "string" ? search.q : "";

  if (query.length === 0) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState
          title="Search this organization"
          description="Type at least one character to look through issues, and — on the higher plans — comments and projects too."
        />
      </div>
    );
  }

  const parsed = searchQuerySchema.safeParse({
    orgId: org.id,
    q: query,
    kinds: advanced ? ["issue", "comment", "project"] : ["issue"],
    limit: RESULT_LIMIT,
  });

  if (!parsed.success) {
    return (
      <div className="space-y-8">
        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
        <EmptyState title="That query is not valid" description="Try something shorter." />
      </div>
    );
  }

  const page = await runSearch(actor, parsed.data);

  return (
    <div className="space-y-8">
      <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />

      {page.items.length === 0 ? (
        <EmptyState title={`Nothing matches “${query}”`} />
      ) : (
        <ul className="space-y-4">
          {page.items.map((hit) => (
            <li key={`${hit.kind}:${hit.id}`}>
              <Link href={hit.href} className="block">
                <span className="text-xs uppercase tracking-wide text-slate-400">
                  {hit.kind}
                </span>
                <span className="mt-0.5 block text-sm font-medium">
                  {hit.title}
                </span>
                <span className="mt-0.5 block text-sm text-slate-600">
                  {hit.snippet}
                </span>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function SearchHeader(props: {
  orgSlug: string;
  query: string;
  advanced: boolean;
}) {
  return (
    <header>
      <h1 className="text-2xl font-semibold tracking-tight">Search</h1>
      <form action={`/${props.orgSlug}/search`} className="mt-4 max-w-md">
        <input
          name="q"
          type="search"
          defaultValue={props.query}
          placeholder="Search issues…"
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </form>
      {!props.advanced ? (
        <p className="mt-2 text-xs text-slate-500">
          Comments and projects are searchable on the growth plan and above.
        </p>
      ) : null}
    </header>
  );
}
